import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1793550481000}'),o={name:"reference/cli.md"};function i(l,e,d,p,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>This page lists every <code>mcp-lens</code> command with its exact flags and defaults, so you can look one up without re-running <code>--help</code>. For a first run end to end, see <a href="/MCPLens/quick-start">Quick Start</a>; for what the report&#39;s columns mean, see <a href="/MCPLens/guide/reading-reports">Reading Reports</a>.</p><p>All commands share the same entry point:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens &lt;command&gt; [options]</span></span></code></pre></div><p>Only <code>scan</code> and <code>auth</code> write to the database, so only they take the writer lease and contend with the VS Code extension. <code>report</code> opens the database but only ever writes an incidental log backfill; if the extension holds the lease it silently skips that save and still prints the same report, read-only. For why a writer lease exists at all, see <a href="/MCPLens/concepts/how-it-works">How It Works</a>.</p><h2 id="report" tabindex="-1">report <a class="header-anchor" href="#report" aria-label="Permalink to &quot;report&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens report [--days &lt;n&gt;] [--format &lt;f&gt;]</span></span></code></pre></div><p>Prints the cost x usage matrix: every scanned tool&#39;s definition token cost next to how often it was actually called, with a recommended action per row. This is the default command, so plain <code>mcp-lens</code> runs it too.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--days &lt;n&gt;</code></td><td><code>30</code></td><td>Aggregate only the last <code>n</code> days. Must be a number greater than 0.</td></tr><tr><td><code>--format &lt;f&gt;</code></td><td><code>table</code></td><td>Output format: <code>table</code>, <code>ai</code>, or <code>json</code>.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> table</span></span></code></pre></div><p>The table has eleven columns. This excerpt keeps only 3 of the real rows so the block stays short, but every column is real:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server          tool                     defTokens  calls  respTokens  loaded/sessions  errorRate  errorTokens  action  confidence  reason</span></span>
<span class="line"><span>--------------  -----------------------  ---------  -----  ----------  ---------------  ---------  -----------  ------  ----------  ------------------------------------------------------------------------------------------------------------------------------------------</span></span>
<span class="line"><span>web-search      web-search_place_search  17251      0      0           0/533            -          0            remove  medium      definition 17,251 tokens, 0 calls. small savings, but cleans up the search space. 98 sessions/3d observed, confirmed with more observation</span></span>
<span class="line"><span>knowledge-base  knowledge-base-search    1809       10     124         5/533            0%         0            keep    high        called 10 times</span></span>
<span class="line"><span>weather-tools   get_weather              74         4      83          3/533            0%         0            keep    high        called 4 times</span></span>
<span class="line"><span></span></span>
<span class="line"><span>savings: potential=61893 actual=26839 saved=35054</span></span>
<span class="line"><span>(0 session files backfilled)</span></span></code></pre></div><p><code>--format ai</code> prints the same data as Markdown, with row-reason templates deduplicated into a &quot;Row reason templates&quot; section above the table. This is the format the <code>/lens-audit</code> slash command consumes, and it is also the shape to paste into a chat with an LLM when you want it to reason about which tools to turn off.</p><h2 id="scan" tabindex="-1">scan <a class="header-anchor" href="#scan" aria-label="Permalink to &quot;scan&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens scan [--config &lt;path&gt;]</span></span></code></pre></div><p>Connects briefly to every configured MCP server, calls <code>tools/list</code>, and records each tool&#39;s definition token count. It spends no LLM tokens and never edits a client config file.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--config &lt;path&gt;</code></td><td>every detected client config</td><td>Read and scan only this one config file instead of auto-discovering every client&#39;s config.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span></span></code></pre></div><p>The <code>discovered:</code> line lists how many servers were found per config source (<code>claude-user</code>, <code>claude-project</code>, <code>codex</code>, <code>gemini</code>), joined with <code>·</code>. The example below shows the real format with illustrative counts:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>discovered: claude-user 2 · codex 1</span></span>
<span class="line"><span>- web-search: 9 tools, 26198 tokens</span></span>
<span class="line"><span>- knowledge-base: 15 tools, 24157 tokens</span></span></code></pre></div><p><code>scan</code> writes to the database, so it takes the writer lease. If the VS Code extension currently holds it, the command prints a message and exits with a non-zero status instead of overwriting the extension&#39;s observations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The VS Code extension is writing the MCP Lens DB, so this command cannot run right now.</span></span>
<span class="line"><span>Close the extension window (or the other running mcp-lens) and try again. It may also clear on its own shortly.</span></span></code></pre></div><h2 id="auth" tabindex="-1">auth <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;auth&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens auth &lt;serverName&gt; [--clear]</span></span></code></pre></div><p>Runs an OAuth login for one HTTP MCP server, then rescans just that server. Use it for servers that require sign-in before <code>tools/list</code> succeeds.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--clear</code></td><td>off</td><td>Delete the stored credentials for <code>&lt;serverName&gt;</code> instead of logging in.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>github: login complete, 12 tools · 3410 tokens</span></span></code></pre></div><p>Like <code>scan</code>, <code>auth</code> writes to the database and takes the writer lease, but only around the final save; the browser sign-in itself happens before the lease is requested, so a slow login does not block the extension. If the server refuses automatic client registration (for example GitHub&#39;s or Figma&#39;s remote MCP servers), the command prints the config key to set an OAuth client id under, or the header to use a personal access token instead.</p><h2 id="hooks-status" tabindex="-1">hooks status <a class="header-anchor" href="#hooks-status" aria-label="Permalink to &quot;hooks status&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hooks status [--json]</span></span></code></pre></div><p>Shows per-client hook installation state: whether the hook package is installed, whether its trust state is approved (Codex only), whether the bundled runner is present, the last observed hook event, how many events are still pending, and an overall health.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--json</code></td><td>off</td><td>Print the same data as JSON instead of the human-readable form.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Field names and shape below are real (one block per client, <code>client / package / trust / runner / last event / pending / fallback / health</code>); the values are illustrative, not a captured run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude Code</span></span>
<span class="line"><span>  package: installed</span></span>
<span class="line"><span>  trust: not-required</span></span>
<span class="line"><span>  runner: ready</span></span>
<span class="line"><span>  last event: &lt;ISO timestamp of the most recent inbox event, or &quot;none&quot;&gt;</span></span>
<span class="line"><span>  pending: 0</span></span>
<span class="line"><span>  fallback: unknown</span></span>
<span class="line"><span>  health: idle</span></span></code></pre></div><h2 id="hooks-doctor" tabindex="-1">hooks doctor <a class="header-anchor" href="#hooks-doctor" aria-label="Permalink to &quot;hooks doctor&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hooks doctor [client]</span></span></code></pre></div><p>Diagnoses the hook setup and prints one line per finding, worst severity first. Pass a client name to check only that one.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Values</th></tr></thead><tbody><tr><td><code>client</code> (optional)</td><td><code>claude-code</code>, <code>codex</code>, <code>gemini-cli</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcp-lens</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] codex codex-trust-unapproved: Codex hook trust is not approved; review it with /hooks.</span></span></code></pre></div><h2 id="hook-capture" tabindex="-1">hook capture <a class="header-anchor" href="#hook-capture" aria-label="Permalink to &quot;hook capture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mcp-lens hook capture --client &lt;c&gt;</span></span></code></pre></div><p>This is the hook runtime&#39;s entry point, not a command for humans to run directly. Claude Code, Codex, and Gemini CLI invoke it as a lifecycle hook, piping the hook payload to it on stdin. It decodes the payload, queues an observation into <code>~/.mcplens/inbox</code>, and always prints <code>{}</code> on stdout and exits 0, even when the payload is invalid or <code>--client</code> is missing or unrecognized. This fail-open contract exists so a bug here can never block your coding session.</p>`,45)])])}const g=s(o,[["render",i]]);export{u as __pageData,g as default};
